const norm = s => (s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9x ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const STOP = new Set(['de','del','la','el','los','las','y','con','para','the','of','tile','box','boxes','ref','bags','bag']);

function score(query, item) {
  const q = norm(query).split(' ').filter(w => w && !STOP.has(w));
  const target = norm(item.descripcion + ' ' + (item.formato || ''));
  if (!q.length) return 0;
  let hits = 0;
  for (const w of q) if (target.includes(w)) hits++;
  return hits / q.length;
}

// The same window decides 'uncertain' and which candidates the human sees - one constant, no drift.
const CANDIDATE_WINDOW = 0.25;

// CUSTOMERS below is generated from data/customers.csv (embedded so the workflow runs standalone).
// If you change the CSV, regenerate this block: the two must never drift apart.
const CUSTOMERS = [
  { codigo: 'C001', nombre: 'Almacenes Vega SL', dominios: ['almacenesvega-demo.es'], condiciones_pago: '30 dias' },
  { codigo: 'C002', nombre: 'Construcciones Prado SL', dominios: ['construccionesprado-demo.es'], condiciones_pago: 'contado' },
