  { codigo: 'C005', nombre: 'Grupo Reformas Levante SL', dominios: ['reformaslevante-demo.es'], condiciones_pago: 'contado' },
  { codigo: 'C006', nombre: 'Almacen del Azulejo Sur SL', dominios: ['azulejosur-demo.es'], condiciones_pago: '45 dias' },
  { codigo: 'C007', nombre: 'BricoNorte Distribucion SL', dominios: ['briconorte-demo.es'], condiciones_pago: '30 dias' },
  { codigo: 'C008', nombre: 'Ceramicas y Banos Ruiz SL', dominios: ['ceramicasruiz-demo.es'], condiciones_pago: '30 dias' }
];

const input = $json;
const ex = input.extraction || {};
const lines = Array.isArray(ex.lines) ? ex.lines : [];

// Customer resolved from the SENDER DOMAIN against the customer table - not from what the email claims.
const senderMatch = String(input.originalText || '').match(/^\s*(?:De|From):\s*.*?([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/mi);
const senderEmail = senderMatch ? senderMatch[1].toLowerCase() : null;
const senderDomain = senderEmail ? senderEmail.split('@')[1] : null;
const custHit = senderDomain ? CUSTOMERS.find(c => c.dominios.includes(senderDomain)) : null;
const customer = custHit
  ? { code: custHit.codigo, name: custHit.nombre, payment_terms: custHit.condiciones_pago, matched_by: 'sender domain' }
  : { code: null, name: ex.customer_hint || null, payment_terms: null, matched_by: 'unresolved - human must confirm' };

const resolved = lines.map(line => {
  const qty = typeof line.quantity === 'number' && line.quantity > 0 ? line.quantity : null;
  const out = { ...line, quantity: qty, matched: null, confidence: 'not_found', candidates: [], warning: null };

  if (line.reference) {
    const exact = CATALOG.find(c => c.referencia.toUpperCase() === String(line.reference).toUpperCase().trim());
    if (exact) {
      out.matched = exact;
      out.confidence = 'high';
    } else {
      out.confidence = 'not_found';
      // Closest catalog products by description travel as SUGGESTIONS only - never as a silent fix.
      const sug = line.description
        ? CATALOG.map(c => ({ item: c, s: score(line.description, c) })).filter(x => x.s >= 0.5).sort((a, b) => b.s - a.s)
        : [];
      out.candidates = sug.filter(x => sug[0].s - x.s < CANDIDATE_WINDOW).slice(0, 3).map(x => x.item);
      out.warning = 'Reference ' + line.reference + ' is not in the catalog' + (out.candidates.length ? ' - closest products shown as suggestions' : '');
      return out;
    }
  }

  if (!out.matched && line.description) {
    const scored = CATALOG
      .map(c => ({ item: c, s: score(line.description, c) }))
      .filter(x => x.s >= 0.5)
      .sort((a, b) => b.s - a.s);

    if (scored.length === 0) {
      out.warning = 'No catalog product matches this description';
      out.confidence = 'not_found';
    } else if (scored.length === 1 || scored[0].s - scored[1].s >= CANDIDATE_WINDOW) {
      out.matched = scored[0].item;
      out.confidence = 'high';
    } else {
      // Only products genuinely competing with the best one are shown to the human (same window as the decision).
      out.candidates = scored.filter(x => scored[0].s - x.s < CANDIDATE_WINDOW).slice(0, 3).map(x => x.item);
      out.confidence = 'uncertain';
      out.warning = 'Description matches more than one product - a human must choose';
    }
  }

  // Unit conversion m2 -> boxes, using the catalog. Never guessed.
  if (out.matched && line.unit === 'm2' && out.matched.m2_por_caja && qty) {
    const boxes = Math.ceil(qty / out.matched.m2_por_caja);
    out.convertedQuantity = boxes;
    out.convertedUnit = 'cajas';
    out.conversionNote = qty + ' m2 / ' + out.matched.m2_por_caja + ' m2 per box = ' + boxes + ' boxes (rounded up)';
  }

  if (out.matched && qty === null) {
    out.confidence = 'uncertain';
    out.warning = 'Quantity not stated in the email';
  }

  return out;
});

const needsReview = resolved.filter(l => l.confidence !== 'high').length;

return [{ json: { ...input, senderEmail, customer, resolvedLines: resolved, needsReview, isOrder: ex.is_order === true } }];

// Build the order proposal a human will review: lines, prices, warnings.
const j = $json;
const UNIT_OF_SALE = { caja: 'cajas', saco: 'sacos', kit: 'kits' };
const lines = j.resolvedLines.map((l, i) => {
  const qty = l.convertedQuantity ?? l.quantity;
  const unit = l.convertedUnit ?? l.unit;
  const price = l.matched ? l.matched.precio_caja_eur : null;
  // A line only gets a price when its final unit IS the catalog sale unit. Anything else stays for the human.
  const saleUnit = l.matched ? UNIT_OF_SALE[l.matched.unidad_venta] : null;
  const priceable = price != null && typeof qty === 'number' && unit === saleUnit;
  let warning = l.warning;
  if (l.matched && typeof qty === 'number' && !priceable) {
    const unitMsg = 'Unit "' + (unit || '?') + '" is not the sale unit (' + l.matched.unidad_venta + ') - price left for review';
    warning = warning ? warning + ' | ' + unitMsg : unitMsg;
  }
  return {
    n: i + 1,
    source: l.raw_text,
    reference: l.matched?.referencia || l.reference || '-',
    product: l.matched?.descripcion || l.description || '-',
    format: l.matched?.formato || '',
    quantity: qty ?? '?',
    unit: unit || '',
    unitPrice: price,
    lineTotal: priceable ? Number((price * qty).toFixed(2)) : null,
    status: l.confidence,
    warning,
    candidates: (l.candidates || []).map(c => c.referencia + ' - ' + c.descripcion + ' ' + c.formato)
  };
});

const total = lines.reduce((s, l) => s + (l.lineTotal || 0), 0);

const summary = lines.map(l =>
  l.n + '. [' + l.status.toUpperCase() + '] ' + l.reference + ' - ' + l.product + ' ' + l.format + ' | ' + l.quantity + ' ' + l.unit +
  (l.lineTotal !== null ? ' | ' + l.lineTotal.toFixed(2) + ' EUR' : '') +
  (l.warning ? '\n     [!] ' + l.warning : '') +
  (l.candidates.length ? '\n     candidates: ' + l.candidates.join(' | ') : '')
).join('\n');

const cust = j.customer || {};
const customerLabel = (cust.name || j.extraction.customer_hint || '?') + (cust.code ? ' (' + cust.code + ' - ' + cust.payment_terms + ')' : ' [NOT RESOLVED - confirm customer]');

return [{ json: { ...j, proposal: { customer: customerLabel, customerCode: cust.code || '', paymentTerms: cust.payment_terms || '', requestedDelivery: j.extraction.requested_delivery, logisticsNotes: j.extraction.logistics_notes, lines, total: Number(total.toFixed(2)) }, proposalText: summary } }];

