// "ERP" write. In the demo the rows are appended to orders-log.csv; in production this is the ERP API or DB.
const gate = $json;
const ctx = $('Build order proposal').first().json;
const orderId = 'DEMO-' + String(Date.now()).slice(-6);
// Who SUBMITTED the email (first form) and who APPROVED at the gate are recorded separately on purpose.
const approvedBy = gate['Approved by (name)'] || ctx.reviewer;

const rows = ctx.proposal.lines.map(l => ({
  order_id: orderId,
  customer_code: ctx.proposal.customerCode || '',
  customer: ctx.proposal.customer,
  reference: l.reference,
  product: l.product,
  quantity: l.quantity,
  unit: l.unit,
  line_total_eur: l.lineTotal,
  submitted_by: ctx.reviewer,
  approved_by: approvedBy,
  decision: gate.Decision
}));

return [{ json: { ...ctx, orderId, decision: gate.Decision, corrections: Number(gate['Lines corrected by hand'] || 0), reviewerNotes: gate['Corrections or rejection reason'] || '', approvedBy, erpRows: rows } }];

// Telemetry: this is what turns "it works" into a measured number. One row per run, approved or not.
const j = $json;
const cfg = $('AI config').first().json;
let ctx = null;
try { ctx = $('Build order proposal').first().json; } catch (e) { ctx = null; }
let base = ctx;
if (!base) { try { base = $('Match against catalog').first().json; } catch (e) { base = {}; } }

const lines = ctx ? ctx.proposal.lines : [];
const totalLines = lines.length;
const autoResolved = lines.filter(l => l.status === 'high').length;
const flagged = totalLines - autoResolved;
const corrections = typeof j.corrections === 'number' ? j.corrections : 0;

let startedAt = base.startedAt;
if (!startedAt) { try { startedAt = $('Normalize text').first().json.startedAt; } catch (e) { startedAt = null; } }
const cycleMs = startedAt ? (new Date() - new Date(startedAt)) : null;

// Two honest metrics instead of one muddled one:
// - first_pass_accuracy: how much the machine resolved ALONE, before any human touch.
// - human_correction_rate: of what was flagged for review, how much the human actually changed.
return [{ json: {
  order_id: j.orderId ?? null,
  outcome: j.decision ?? j.outcome ?? 'rejected',
  total_lines: totalLines,
  auto_resolved_lines: autoResolved,
  flagged_lines: flagged,
  human_corrections: corrections,
  first_pass_accuracy_pct: totalLines ? Number((autoResolved / totalLines * 100).toFixed(1)) : null,
  human_correction_rate_pct: flagged ? Number((corrections / flagged * 100).toFixed(1)) : null,
  cycle_seconds: cycleMs !== null ? Number((cycleMs / 1000).toFixed(1)) : null,
  reviewer: base.reviewer || null,
  model: cfg.model,
  prompt_version: cfg.prompt_version
} }];

// Rejected or not an order: logged with the reason, never silently dropped.
const j = $json;
const ctx = $('Match against catalog').first().json;
return [{ json: {
  outcome: ctx.isOrder ? 'rejected_by_human' : 'not_an_order',
  reason: ctx.isOrder ? (j['Corrections or rejection reason'] || 'no reason given') : (ctx.extraction?.not_order_reason || 'the email is not a purchase order'),
  originalText: ctx.originalText
} }];

// Append-ready CSV rows for the "ERP" log. No header here: results/orders-log.csv ships with it.
const esc = v => { const s = v === null || v === undefined ? '' : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const rows = $json.erpRows.map(r => [r.order_id, r.customer_code, r.customer, r.reference, r.product, r.quantity, r.unit, r.line_total_eur, r.submitted_by, r.approved_by, r.decision].map(esc).join(','));
const text = rows.join('\n') + '\n';
return [{ json: { csv: text }, binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/csv', fileName: 'orders-log.csv' } } }];

// One telemetry CSV row per run. No header here: results/telemetry-log.csv ships with it.
const esc = v => { const s = v === null || v === undefined ? '' : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const t = $json;
const row = [t.order_id, t.outcome, t.total_lines, t.auto_resolved_lines, t.flagged_lines, t.human_corrections, t.first_pass_accuracy_pct, t.human_correction_rate_pct, t.cycle_seconds, t.reviewer, t.model, t.prompt_version].map(esc).join(',') + '\n';
return [{ json: t, binary: { data: { data: Buffer.from(row, 'utf8').toString('base64'), mimeType: 'text/csv', fileName: 'telemetry-log.csv' } } }];
